#!/usr/bin/env node
// One-off, deterministic and idempotent: gives every item of src/data/items.json its `kind` and the estimates the kind contracts need.
//
// items.json is generated by tools/items-catalog from the team deliveries. What this script adds is kept in
// tools/items-catalog/kinds-overlay.json (id -> fields), which the generator merges over each generated row, so a regeneration
// reproduces this file. Running the script again reads the overlay, strips it from the rows and applies the rules again: same result.
//
//   node packages/game-items-goods/scripts/migrate-kinds.mjs
//
// Every field the script fills is named in the item's `estimated` list: "estimated from the real world, the teams may adjust it".
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..')
const ITEMS_PATH = join(root, 'packages', 'game-items-goods', 'src', 'data', 'items.json')
const OVERLAY_PATH = join(root, 'tools', 'items-catalog', 'kinds-overlay.json')

const list = (text) => text.trim().split(/\s+/)

// ---- kind of each item -------------------------------------------------------------------------------------------------------------------------
const KIND_IDS = {
  canned_food: 'canned_beans canned_sardines canned_corn_and_peas canned_sausages condensed_milk canned_food',
  food_needs_prep: 'rice beans pasta raw_beef frozen_chicken eggs potatoes cassava_root fresh_fish game_meat instant_noodles frozen_meat frozen_vegetables',
  food_improves_cooked: 'bread sandwich leftover_meal ham mortadella frozen_pizza military_ration',
  ingredient: 'sugar salt cooking_oil flour cassava_flour seasoning butter ketchup coffee',
  food_ready: 'biscuits snack_chips chocolate_bar rapadura honey_jar cheese orange banana_bunch apple tomato cereal_box yogurt ice_cream jerked_beef salted_fish home_preserves dog_food',
  drink_ready: 'water_bottle water_jug_5l juice_box milk_carton sports_drink energy_drink coconut_water cachaca communion_wine',
  canned_drink: 'soda_can beer_can',
  drink_untreated: 'dirty_water',
  medicine: 'painkillers ibuprofen tramadol clonazepam amoxicillin ceftriaxone activated_charcoal rehydration_salts antihistamine antivenom maintenance_medication multivitamin insulin povidone_iodine alcohol_70 saline_iv_bag',
  first_aid: 'bandage sterile_gauze adhesive_bandages medical_tape syringe suture_kit splint first_aid_kit exam_gloves n95_mask',
  hygiene: 'soap shampoo toothpaste toothbrush deodorant toilet_paper towel',
  cookware: 'pot pan',
  tableware: 'plate bowl cup wine_glass',
  tank: 'bucket barrel watering_can',
  metal_can: 'paint_can empty_can shoe_polish',
  plastic_bottle: 'pet_bottle empty_bottle',
  glass_bottle: 'glass_bottle',
  jar: 'glass_jar',
  ranged: 'slingshot recurve_bow crossbow',
  ammo: 'arrows_and_bolts',
  camping: 'camp_stove ice_pack blanket pillow candles charcoal_bag tongs skewers firelighter',
  electronics: 'cordless_drill car_battery_12v',
  fuel: 'fuel_jerrycan gasoline diesel lpg_cylinder_13kg gas_cartridge kerosene motor_oil',
  tool: 'thermometer extension_cord cable_bundle pen stapler fishing_rod fishing_tackle_box fishing_net snare_trap',
  material: 'bean_seeds corn_seeds pumpkin_seeds kale_and_lettuce_seeds cassava_cuttings fertilizer_bag',
}
const KIND_OF = new Map()
for (const [kind, ids] of Object.entries(KIND_IDS)) for (const id of list(ids)) KIND_OF.set(id, kind)
const KIND_BY_CATEGORY = { tools: 'tool', melee: 'melee', materials: 'material', clothing: 'clothing', bags: 'bag', electronics: 'electronics', books: 'book', collectibles: 'collectible', keys: 'key' }
const kindOf = (item) => {
  const kind = KIND_OF.get(item.id) ?? KIND_BY_CATEGORY[item.category]
  if (!kind) throw new Error(`migrate-kinds: no kind for "${item.id}" (category ${item.category})`)
  return kind
}

// ---- estimates ---------------------------------------------------------------------------------------------------------------------------------
const NUTRITION = {
  canned_food: [25, -5, 730], flour: [5, -8, 365], cereal_box: [18, -5, 270], butter: [8, -4, 90], ketchup: [2, 0, 365], ham: [16, -3, 30],
  yogurt: [10, 5, 28], apple: [8, 6, 21], tomato: [5, 8, 10], frozen_meat: [20, -2, 180], ice_cream: [10, 4, 180], frozen_pizza: [28, -6, 180],
  frozen_vegetables: [10, 3, 270], sandwich: [22, -3, 2], seasoning: [1, -2, 730],
}
const NON_PERISHABLE = list('honey_jar sugar salt water_bottle water_jug_5l dirty_water cachaca communion_wine')
const NEEDS_COOKABLE = list('instant_noodles frozen_meat frozen_vegetables')
const FLUID = {
  water_bottle: ['water', 0.5], water_jug_5l: ['water', 5], juice_box: ['juice', 0.2], milk_carton: ['milk', 1], sports_drink: ['juice', 0.5],
  energy_drink: ['soda', 0.25], coconut_water: ['juice', 0.33], cachaca: ['spirits', 0.7], communion_wine: ['wine', 0.75], soda_can: ['soda', 0.35],
  beer_can: ['beer', 0.35], dirty_water: ['water', 0.5], fuel_jerrycan: ['fuel', 5], gasoline: ['fuel', 1], diesel: ['diesel', 1],
  lpg_cylinder_13kg: ['gas', 24], gas_cartridge: ['gas', 0.58], kerosene: ['fuel', 1], motor_oil: ['motor_oil', 1],
}
const CAPACITY = { bucket: 10, barrel: 60, watering_can: 5 }
const CHARGE = {
  flashlight: 0.02, headlamp: 0.02, power_bank: 0.03, folding_solar_panel: 0, portable_radio: 0.02, walkie_talkies: 0.02, cb_radio: 0.02, military_radio: 0.02,
  portable_generator: 0, led_camp_lantern: 0.02, mobile_phone: 0.03, laptop: 0.03, windup_alarm_clock: 0, car_alarm_remote: 0.01,
  electric_fence_energizer: 0.02, night_vision_goggles: 0.02, phone_charger: 0, remote_control: 0.02, cordless_drill: 0.03, car_battery_12v: 0.05,
}
const PROTECTION = {
  jacket: { slots: ['torso', 'arms'], bite: 0.1, scratch: 0.25, warmth: 0.4 },
  socks: { slots: ['feet'], bite: 0, scratch: 0.02, warmth: 0.15 },
  underwear: { slots: ['legs'], bite: 0, scratch: 0.01, warmth: 0.05 },
  hat: { slots: ['head'], bite: 0, scratch: 0.05, warmth: 0.2 },
  scarf: { slots: ['torso'], bite: 0.05, scratch: 0.02, warmth: 0.2 },
  rubber_gloves: { slots: ['hands'], bite: 0.05, scratch: 0.1, warmth: 0.05 },
  eyeglasses: { slots: ['eyes'], bite: 0, scratch: 0.02, warmth: 0 },
}
/** Weights (kg) of items whose box held less than 0.02 kg/L (air); real-world values. The sizes of crumpled_paper, plastic_bag and food_packaging were fixed in tools/items-catalog/decisions.json. */
const WEIGHT = { shopping_bag: 0.1, delivery_bag: 2, hiking_backpack_40l: 1.8, plastic_bag: 0.01, pet_bottle: 0.08 }

/** [material, thickness?] of the body when the kind's default does not fit the item. */
const MATERIAL = Object.fromEntries(
  Object.entries({
    juice_box: ['paper', 0.0005], milk_carton: ['paper', 0.0005], cachaca: ['glass', 0.003], communion_wine: ['glass', 0.003],
    alcohol_70: ['plastic', 0.001], povidone_iodine: ['plastic', 0.001], saline_iv_bag: ['plastic', 0.0003], insulin: ['glass', 0.002],
    syringe: ['plastic', 0.001], splint: ['wood_soft', 0.01], first_aid_kit: ['plastic', 0.002], exam_gloves: ['rubber', 0.0001], n95_mask: ['fabric', 0.001],
    pot: ['aluminium', 0.002], wine_glass: ['glass', 0.002],
    baseball_bat: ['wood_hard', 0.03], nail_bat: ['wood_hard', 0.03], improvised_spear: ['wood_soft', 0.02], cast_iron_skillet: ['cast_iron', 0.004],
    police_baton: ['aluminium', 0.003], arrows_and_bolts: ['wood_soft', 0.005],
    leather_motorcycle_jacket: ['leather', 0.002], leather_motorcycle_pants: ['leather', 0.002], combat_boots: ['leather', 0.003], leather_work_gloves: ['leather', 0.0015],
    rubber_boots: ['rubber', 0.004], flip_flops: ['rubber', 0.008], rubber_gloves: ['rubber', 0.0005], sneakers: ['rubber', 0.006],
    motorcycle_helmet: ['plastic', 0.005], hard_hat: ['plastic', 0.004], safety_goggles: ['plastic', 0.002], eyeglasses: ['plastic', 0.002],
    sheet_metal_forearm_guard: ['steel', 0.001], magazine_arm_guard: ['paper', 0.005],
    shopping_cart: ['steel', 0.002], wheelbarrow: ['steel', 0.0015], cooler_box: ['plastic', 0.004], rolling_suitcase: ['plastic', 0.003], trash_bag: ['plastic', 0.0002], tool_belt: ['leather', 0.003],
    broomstick: ['wood_soft', 0.015], broom: ['wood_soft', 0.015], lighter: ['plastic', 0.001], matches: ['paper', 0.0005], binoculars: ['plastic', 0.003], clothespins: ['wood_soft', 0.003],
    electrical_tape: ['rubber', 0.0002], duct_tape: ['fabric', 0.0003], sewing_kit: ['fabric', 0.002], fishing_rod: ['wood_hard', 0.01], fishing_tackle_box: ['plastic', 0.002],
    fishing_net: ['fabric', 0.001], thermometer: ['plastic', 0.001], pen: ['plastic', 0.001], stapler: ['plastic', 0.002], sharpening_stone: ['stone', 0.02],
    extension_cord: ['rubber', 0.002], cable_bundle: ['rubber', 0.002], portable_generator: ['steel', 0.001],
    lpg_cylinder_13kg: ['steel', 0.003], gas_cartridge: ['steel', 0.0005],
    camp_stove: ['steel', 0.001], ice_pack: ['plastic', 0.001], tongs: ['steel', 0.002], skewers: ['steel', 0.002], firelighter: ['paper', 0.001], charcoal_bag: ['paper', 0.0005], candles: ['wax', 0.01],
    nails: ['steel', 0.003], screws: ['steel', 0.003], sheet_metal: ['steel', 0.001], scrap_metal: ['steel', 0.002], wire_roll: ['steel', 0.002], barbed_wire: ['steel', 0.002],
    rope: ['fabric', 0.01], tarp: ['fabric', 0.0005], raffia_sack: ['fabric', 0.0005], bricks: ['brick', 0.1], cement_bag: ['paper', 0.0005], rag: ['fabric', 0.001],
    glass_shards: ['glass', 0.003], epoxy_glue: ['plastic', 0.001], electronic_components: ['plastic', 0.002], copper_wire: ['copper', 0.001], rebar: ['steel', 0.012],
    lubricant_spray: ['aluminium', 0.0003], detergent: ['plastic', 0.001], bleach: ['plastic', 0.001], sponge: ['foam', 0.03], crumpled_paper: ['paper', 0.0001],
    food_scraps: ['flesh_fruit', 0.02], plastic_bag: ['plastic', 0.00002], feather: ['fabric', 0.0005], bread_mold: ['foliage', 0.005], disinfectant: ['plastic', 0.001],
    laundry_powder: ['paper', 0.0005], fabric_softener: ['plastic', 0.001], full_trash_bag: ['plastic', 0.0002], food_packaging: ['paper', 0.0003],
    bean_seeds: ['paper', 0.0003], corn_seeds: ['paper', 0.0003], pumpkin_seeds: ['paper', 0.0003], kale_and_lettuce_seeds: ['paper', 0.0003], cassava_cuttings: ['green_wood', 0.02],
    fertilizer_bag: ['paper', 0.0005], dog_tag: ['steel', 0.001], wallet: ['leather', 0.002], dvd: ['plastic', 0.001], access_badge: ['plastic', 0.001],
    soap: ['wax', 0.01], deodorant: ['aluminium', 0.0003], toilet_paper: ['paper', 0.001], towel: ['fabric', 0.005],
  }).map(([id, [material, thickness]]) => [id, { id: 'body', material, thickness }]),
)
/** Glass drinks break like glass and leave a bottle, paper packs leave their wrapper. */
const EXTRAS = {
  cachaca: { impact: { response: 'shatter', pushImpulse: true, shed: true }, leftover: { item: 'glass_bottle', despawnSeconds: 600 } },
  communion_wine: { impact: { response: 'shatter', pushImpulse: true, shed: true }, leftover: { item: 'glass_bottle', despawnSeconds: 600 } },
  juice_box: { impact: { response: 'squash', pushImpulse: true }, leftover: { item: 'food_packaging', despawnSeconds: 300 } },
  milk_carton: { impact: { response: 'squash', pushImpulse: true }, leftover: { item: 'food_packaging', despawnSeconds: 300 } },
  baseball_bat: { impact: { response: 'break', pushImpulse: true } },
  nail_bat: { impact: { response: 'break', pushImpulse: true } },
  improvised_spear: { impact: { response: 'break', pushImpulse: true } },
  sheet_metal_forearm_guard: { impact: { response: 'dent', pushImpulse: false } },
}
const AMMO_CALIBER = { arrows_and_bolts: 'arrow' }

// ---- the patch of one item ---------------------------------------------------------------------------------------------------------------------
const patchOf = (item) => {
  const patch = { kind: kindOf(item) }
  const estimated = []
  const set = (field, value) => {
    patch[field] = value
    estimated.push(field)
  }
  if (NUTRITION[item.id]) {
    const [satiety, hydration, shelfLife] = NUTRITION[item.id]
    set('nutrition', { satiety, hydration })
    set('shelfLife', shelfLife)
  }
  if (NON_PERISHABLE.includes(item.id)) set('nonPerishable', true)
  if (NEEDS_COOKABLE.includes(item.id)) set('cookable', true)
  if (FLUID[item.id]) set('fluid', { liquid: FLUID[item.id][0], liters: FLUID[item.id][1] })
  if (CAPACITY[item.id]) set('container', { capacityLiters: CAPACITY[item.id] })
  if (CHARGE[item.id] !== undefined) set('charge', { lossPerMonth: CHARGE[item.id] })
  if (PROTECTION[item.id]) set('protection', PROTECTION[item.id])
  if (AMMO_CALIBER[item.id]) set('caliber', AMMO_CALIBER[item.id])
  if (MATERIAL[item.id]) set('parts', [MATERIAL[item.id]])
  for (const [field, value] of Object.entries(EXTRAS[item.id] ?? {})) set(field, value)
  if (WEIGHT[item.id] !== undefined) set('weight', WEIGHT[item.id])
  if (estimated.length > 0) patch.estimated = estimated
  return patch
}

/** The row with the patch merged over it: `kind` right after `category`, fields the row has stay in place, new ones go last. */
const mergeRow = (row, patch) => {
  const out = {}
  for (const key of Object.keys(row)) {
    out[key] = key in patch ? patch[key] : row[key]
    if (key === 'category' && !('kind' in row)) out.kind = patch.kind
  }
  for (const key of Object.keys(patch)) if (!(key in out)) out[key] = patch[key]
  return out
}

const read = (path, fallback) => {
  try {
    return JSON.parse(readFileSync(path, 'utf8'))
  } catch {
    return fallback
  }
}

const items = read(ITEMS_PATH)
const previous = read(OVERLAY_PATH, {})
const overlay = {}
const rows = items.map((row) => {
  // Strip what an earlier run added (weight is kept: the overlay replaces it and the generator's value is not needed).
  const base = Object.fromEntries(Object.entries(row).filter(([key]) => !(key in (previous[row.id] ?? {})) || key === 'weight'))
  const patch = patchOf(base)
  overlay[row.id] = patch
  return mergeRow(base, patch)
})
writeFileSync(OVERLAY_PATH, `${JSON.stringify(overlay, null, 2)}\n`)
writeFileSync(ITEMS_PATH, `${JSON.stringify(rows, null, 2)}\n`)
console.log(`migrate-kinds: ${rows.length} items, ${Object.values(overlay).filter((patch) => patch.estimated).length} with estimated fields`)
